// Value mode, for "pick an icon for this project": the trigger shows the chosen emoji, \`name\` posts it with a plain
// \`<form>\`, \`required\` refuses an empty submit and focuses the trigger, and the Field's label names it.
export function EmojiPickerValueAndForm() {
  const [posted, setPosted] = useState<string | null>(null)
  return (
    <form
      className="flex max-w-sm flex-col gap-3 text-[13px]"
      onSubmit={(event) => {
        event.preventDefault()
        setPosted(JSON.stringify([...new FormData(event.currentTarget)].map(([key, value]) => [key, String(value)])))
      }}
    >
      <Field>
        <FieldLabel>Project icon</FieldLabel>
        <EmojiPicker name="icon" required side="bottom" align="start" />
        <FieldDescription>Shown beside the project's name.</FieldDescription>
        <FieldError match="valueMissing">Pick an icon.</FieldError>
      </Field>
      <Button type="submit" size="sm" className="self-start">
        Save
      </Button>
      <p role="status" className="text-muted-foreground">
        FormData: <code>{posted ?? "not submitted"}</code>
      </p>
    </form>
  )
}
